// Call of Duty iPad - entry point of a game module (see game_module.h).
// Compiled into every module with COD_MODULE_ID set to its id.

#include <rex/image_info.h>

#include "game_module.h"

// Generated by rexglue (<project>_init.cpp) for the module's executable.
extern const rex::PPCImageInfo PPCImageConfig;

// Game-specific settings; modules without hooks use the empty one
// (generic_module.cpp).
void CodApplyModuleSettings(const cod::GameModuleSettings& settings);

extern "C" __attribute__((visibility("default"))) const cod::GameModule* cod_game_module() {
  static const cod::GameModule module{cod::kGameModuleAbi, COD_MODULE_ID, &PPCImageConfig,
                                      &CodApplyModuleSettings};
  return &module;
}
